Object.assign(SNIP,{"l30ptr": "void inSV(const SinhVien& s) {     // truyền tham chiếu const: không chép, không sửa\n    cout << s.ten << \" \" << s.diem << \"\\n\";\n}\nvector<SinhVien> ds = {{\"An\", 7}, {\"Binh\", 9}};\nds[1].diem += 0.5;                 // phần tử vector là đối tượng\nSinhVien* p = &ds[0];\np->diem = 8;                       // p->diem là cách viết gọn của (*p).diem", "l30method": "struct HinhChuNhat {\n    double dai, rong;\n\n    double dienTich() const {      // hàm thành viên: dùng thẳng dai, rong\n        return dai * rong;         // const: hứa không sửa đối tượng\n    }\n    void phongTo(double k) {       // không const: được sửa thành viên\n        dai *= k;\n        rong *= k;\n    }\n};\n\nHinhChuNhat h{3, 2};\ncout << h.dienTich();   // 6: hàm chạy trên chính đối tượng h\nh.phongTo(2);           // dai = 6, rong = 4", "l30def": "struct SinhVien {          // định nghĩa một KIỂU mới tên SinhVien\n    string ten;            // các thành viên dữ liệu (member)\n    double diem;\n    int tuoi = 18;         // giá trị mặc định của thành viên\n};                         // chú ý dấu ; sau dấu }\n\nSinhVien a;                // một biến (đối tượng) kiểu SinhVien\na.ten = \"An\";              // truy cập thành viên bằng dấu chấm\nSinhVien b{\"Binh\", 8.5};   // khởi tạo theo thứ tự khai báo: ten, diem\nSinhVien c = b;            // chép toàn bộ: c là bản sao độc lập của b"});PRESET_NOTES["l30"]={"Ví dụ: Gom dữ liệu bằng struct": "Diem gồm hai int nằm liền nhau: x ở địa chỉ thấp, y ngay sau 4 byte; sizeof(Diem) là 8. s{\"An\", 8.5} gán theo thứ tự khai báo; tuoi không có trong { } nên nhận giá trị mặc định 18. SinhVien chiếm 48 byte: string 32, double 8, int 4 và 4 byte đệm cho tròn bội của 8.", "Ví dụ: Gán là chép từng thành viên": "Diem b = a tạo một đối tượng mới ở địa chỉ khác, chép x, y từ a sang. Sửa b.x không ảnh hưởng a. Câu a = b lại chép ngược từ b sang a.", "Ví dụ: Hàm thành viên và con trỏ this": "Bấm Từng bước vào trong dienTich: khung của hàm có con trỏ this, mũi tên chỉ về h1 ở lần gọi đầu và về h2 ở lần gọi sau. Cùng một hàm, nhưng dai, rong là của đối tượng nào thì do this quyết định.", "Ví dụ: Truyền đối tượng vào hàm": "congDiemBanSao nhận một bản sao: khung của hàm có đối tượng s riêng, cộng xong thì bỏ. congDiem nhận tham chiếu nên s là mũi tên chỉ về a của main, sửa thật. inSV dùng const SinhVien&: không chép và không sửa được.", "Ví dụ: vector đối tượng": "Mỗi phần tử của vector là một đối tượng SinhVien; ds[i].diem là thành viên diem của phần tử thứ i. Tìm vị trí lớn nhất giống hệt với mảng số, chỉ khác là so sánh ds[i].diem.", "Ví dụ: Con trỏ tới đối tượng": "p giữ địa chỉ của a nên p->x chính là a.x. q trỏ tới một đối tượng nằm trên heap (khối #1); nhớ delete q khi xong.", "Lỗi: so sánh hai struct bằng ==": "g++ báo no match for 'operator==': C++ không tự định nghĩa phép so sánh cho kiểu bạn tự tạo. Tạm thời so sánh từng thành viên: a.x == b.x && a.y == b.y. Bài 33 sẽ dạy cách viết toán tử == cho Diem.", "Lỗi: gọi hàm không const trên đối tượng const": "h trong inDT là const nên chỉ gọi được hàm thành viên const. dienTich không sửa gì nhưng quên ghi const, nên g++ báo passing 'const HinhChuNhat' as 'this' argument discards qualifiers. Sửa: double dienTich() const { ... }."};EX_HINTS["l30"]=[["dx = a.x - b.x, dy = a.y - b.y; khoảng cách là sqrt(dx * dx + dy * dy).", "Tham số const Diem& không chép đối tượng và bảo đảm hàm không sửa điểm."], ["Giữ chỉ số k của người cao nhất; so sánh ds[i].diem > ds[k].diem (dấu > để giữ người nhập trước khi bằng nhau).", "Đếm số người đạt trong cùng vòng lặp."], ["Trong hàm thành viên dùng thẳng dai, rong (chính là this->dai, this->rong).", "Ba hàm đều không sửa đối tượng nên ghi const sau dấu ): int dienTich() const { ... }."]];
/* ===================== BÀI 30 · struct và class ===================== */
/* Bài 30 · struct và class
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P30=[{label:"Ví dụ: Gom dữ liệu bằng struct",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x;\n    int y;\n};\n\nstruct SinhVien {\n    string ten;\n    double diem;\n    int tuoi = 18;\n};\n\nint main() {\n    Diem a;\n    a.x = 3;\n    a.y = 4;\n    Diem b{-1, 2};\n    cout << \"a = (\" << a.x << \", \" << a.y << \")\\n\";\n    cout << \"b = (\" << b.x << \", \" << b.y << \")\\n\";\n    SinhVien s{\"An\", 8.5};\n    cout << s.ten << \", \" << s.diem << \" diem, \" << s.tuoi << \" tuoi\\n\";\n    cout << sizeof(Diem) << \" \" << sizeof(s) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Gán là chép từng thành viên",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n};\n\nint main() {\n    Diem a{1, 2};\n    Diem b = a;\n    b.x = 100;\n    cout << \"a = (\" << a.x << \", \" << a.y << \")\\n\";\n    cout << \"b = (\" << b.x << \", \" << b.y << \")\\n\";\n    a = b;\n    cout << \"a = (\" << a.x << \", \" << a.y << \")\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm thành viên và con trỏ this",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct HinhChuNhat {\n    double dai, rong;\n\n    double dienTich() const {\n        return dai * rong;\n    }\n\n    void phongTo(double k) {\n        dai *= k;\n        rong *= k;\n    }\n};\n\nint main() {\n    HinhChuNhat h1{3, 2}, h2{5, 5};\n    cout << h1.dienTich() << \" \" << h2.dienTich() << \"\\n\";\n    h1.phongTo(2);\n    cout << h1.dai << \" x \" << h1.rong << \" = \" << h1.dienTich() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Truyền đối tượng vào hàm",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct SinhVien {\n    string ten;\n    double diem;\n};\n\nvoid congDiemBanSao(SinhVien s) {\n    s.diem += 1;\n}\n\nvoid congDiem(SinhVien& s) {\n    s.diem += 1;\n}\n\nvoid inSV(const SinhVien& s) {\n    cout << s.ten << \": \" << s.diem << \"\\n\";\n}\n\nint main() {\n    SinhVien a{\"An\", 7};\n    congDiemBanSao(a);\n    inSV(a);\n    congDiem(a);\n    inSV(a);\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: vector đối tượng",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct SinhVien {\n    string ten;\n    double diem;\n};\n\nint main() {\n    vector<SinhVien> ds = {{\"An\", 7}, {\"Binh\", 9}, {\"Chi\", 8}};\n    ds.push_back({\"Dung\", 9.5});\n    int k = 0;\n    for (int i = 1; i < (int)ds.size(); i++) {\n        if (ds[i].diem > ds[k].diem) k = i;\n    }\n    cout << \"Cao nhat: \" << ds[k].ten << \" (\" << ds[k].diem << \")\\n\";\n    for (const SinhVien& s : ds) cout << s.ten << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Con trỏ tới đối tượng",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n};\n\nint main() {\n    Diem a{3, 4};\n    Diem* p = &a;\n    p->x = 30;\n    (*p).y = 40;\n    cout << a.x << \" \" << a.y << \"\\n\";\n    Diem* q = new Diem{7, 8};\n    cout << q->x + q->y << \"\\n\";\n    delete q;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: so sánh hai struct bằng ==",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n};\n\nint main() {\n    Diem a{1, 2}, b{1, 2};\n    if (a == b) cout << \"Bang nhau\\n\";\n    return 0;\n}"},{label:"Lỗi: gọi hàm không const trên đối tượng const",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct HinhChuNhat {\n    double dai, rong;\n    double dienTich() {\n        return dai * rong;\n    }\n};\n\nvoid inDT(const HinhChuNhat& h) {\n    cout << h.dienTich() << \"\\n\";\n}\n\nint main() {\n    HinhChuNhat h{3, 2};\n    inDT(h);\n    return 0;\n}"}];
