makeEx2(document.getElementById("ex-l30"),sim30,[{t:"Khoảng cách hai điểm",d:"Nhập tọa độ hai điểm x1 y1 x2 y2 (số thực). Định nghĩa <code>struct Diem { double x, y; };<\/code> và hàm <code>double khoangCach(const Diem&amp; a, const Diem&amp; b)<\/code>. In khoảng cách với 2 chữ số sau dấu phẩy.",tests:[{in:"0 0 3 4",out:"5.00"},{in:"1 1 1 1",out:"0.00"},{in:"-1 2 2 -2",out:"5.00"},{in:"0.5 0 0 0.5",out:"0.71"}],start:"#include <iostream>\n#include <iomanip>\n#include <cmath>\nusing namespace std;\n\nstruct Diem {\n    double x, y;\n};\n\ndouble khoangCach(const Diem& a, const Diem& b) {\n    // căn bậc hai của (dx * dx + dy * dy)\n    return 0;\n}\n\nint main() {\n    Diem a, b;\n    cin >> a.x >> a.y >> b.x >> b.y;\n    cout << fixed << setprecision(2) << khoangCach(a, b) << \"\\n\";\n    return 0;\n}",need:/double\s+khoangCach\s*\(\s*const\s+Diem\s*&\s*\w+\s*,\s*const\s+Diem\s*&\s*\w+\s*\)/,needMsg:"Hãy giữ hàm double khoangCach(const Diem& a, const Diem& b)."},{t:"Sinh viên điểm cao nhất",d:"Nhập n (1 ≤ n ≤ 1000), rồi n dòng, mỗi dòng gồm tên (không có dấu cách) và điểm (số nguyên). Lưu vào <code>vector&lt;SinhVien&gt;<\/code> với <code>struct SinhVien { string ten; int diem; };<\/code>. In tên và điểm của người điểm cao nhất (nếu bằng nhau, lấy người nhập trước), rồi in số người đạt từ 5 điểm trở lên.",tests:[{in:"3\nAn 7\nBinh 9\nChi 8",out:"Binh 9\n3"},{in:"1\nDung 4",out:"Dung 4\n0"},{in:"4\nA 6\nB 10\nC 10\nD 2",out:"B 10\n3"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct SinhVien {\n    string ten;\n    int diem;\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<SinhVien> ds(n);\n    for (int i = 0; i < n; i++) cin >> ds[i].ten >> ds[i].diem;\n    // tìm vị trí điểm cao nhất, đếm số người đạt\n    return 0;\n}",need:/struct\s+SinhVien[\s\S]*vector\s*<\s*SinhVien\s*>/,needMsg:"Hãy dùng struct SinhVien và vector<SinhVien>."},{t:"Hình chữ nhật có hàm thành viên",d:"Nhập chiều dài và chiều rộng (số nguyên dương). Viết <code>struct HinhChuNhat<\/code> có hai thành viên <code>dai<\/code>, <code>rong<\/code> và ba hàm thành viên const: <code>dienTich()<\/code>, <code>chuVi()<\/code>, <code>laHinhVuong()<\/code> (trả về bool). In diện tích, chu vi và YES/NO cho biết có phải hình vuông.",tests:[{in:"3 4",out:"12 14 NO"},{in:"5 5",out:"25 20 YES"},{in:"1 100",out:"100 202 NO"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct HinhChuNhat {\n    int dai, rong;\n    // viết dienTich(), chuVi(), laHinhVuong() là các hàm thành viên const\n};\n\nint main() {\n    HinhChuNhat h;\n    cin >> h.dai >> h.rong;\n    // in h.dienTich(), h.chuVi(), YES/NO\n    return 0;\n}",need:/struct\s+HinhChuNhat\s*\{[\s\S]*dienTich\s*\(\s*\)\s*const[\s\S]*chuVi\s*\(\s*\)\s*const[\s\S]*laHinhVuong\s*\(\s*\)\s*const[\s\S]*\};/,needMsg:"Hãy viết ba hàm thành viên const dienTich(), chuVi(), laHinhVuong() bên trong struct HinhChuNhat."}]);

makeQuiz("quiz30","score30",[{"q": "<code>struct P { int a, b; }; P x{1, 2}; P y = x; y.a = 9;<\/code> Lúc này <code>x.a<\/code> bằng?", "o": ["1", "9", "2", "Lỗi biên dịch"], "a": 0, "e": "P y = x chép từng thành viên: y là đối tượng độc lập, sửa y.a không đổi x.a."}, {"q": "Khác biệt duy nhất giữa struct và class trong C++ là gì?", "o": ["struct không có hàm thành viên", "class không có thành viên dữ liệu", "Quyền truy cập mặc định: struct là public, class là private", "struct nằm trên stack, class nằm trên heap"], "a": 2, "e": "Ngoài quyền truy cập mặc định, struct và class giống hệt nhau."}, {"q": "Với <code>Diem* p = &amp;a;<\/code>, cách nào truy cập thành viên x của a?", "o": ["<code>p.x<\/code>", "<code>*p.x<\/code>", "<code>p-&gt;x<\/code>", "<code>&amp;p.x<\/code>"], "a": 2, "e": "p->x là (*p).x. Viết *p.x sai vì dấu chấm được tính trước dấu *."}, {"q": "Chữ const trong <code>double dienTich() const<\/code> có nghĩa là gì?", "o": ["Hàm trả về hằng số", "Hàm không được sửa thành viên của đối tượng", "Đối tượng phải được khai báo const", "Hàm chỉ gọi được một lần"], "a": 1, "e": "Hàm thành viên const hứa không sửa đối tượng; nhờ vậy nó gọi được cả trên đối tượng const."}]);

